import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.net.UnknownHostException;

public class SecureExample {
    public static void main(String[] args) throws Exception {
        // This string would normally come from untrusted user input
        String userInput = "https://example.com"; 

        // Validate that the input is not empty
        if (userInput == null || userInput.isEmpty()) {
            throw new IllegalArgumentException("URL cannot be empty");
        }

        URL url = new URL(userInput);

        // Check protocol whitelist (only allow http/https)
        String protocol = url.getProtocol().toLowerCase();
        if (!protocol.equals("http") && !protocol.equals("https")) {
            throw new SecurityException("Only HTTP and HTTPS protocols are allowed");
        }

        // Resolve the hostname to prevent SSRF via IP addresses or localhost
        String host = url.getHost();
        InetAddress address = InetAddress.getByName(host);

        // Reject private, loopback, or link-local addresses
        if (address.isAnyLocalAddress() || 
            address.isLoopbackAddress() || 
            address.isLinkLocalAddress() || 
            address.isSiteLocalAddress()) {
            throw new SecurityException("Access denied to private or local addresses");
        }

        // Proceed only after validation passes
        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println(line);
            }
        }
    }
}
